def create_forums(apps, schema_editor):
    # One forum for every club of an active competition; the football sync adds the later ones.
    Team = apps.get_model("sports", "Team")
    Forum = apps.get_model("forums", "Forum")
    for team in Team.objects.filter(competitions__is_active=True).distinct():
        Forum.objects.get_or_create(team=team)


def open_forums_item(apps, schema_editor):
    # The forums are built: the sidebar stops showing them as "soon".
    apps.get_model("header", "SidebarItem").objects.filter(url="/forums").update(is_soon=False)


